from journal.support.option import Option


class FaultsOptions:
    DEVELOPER = Option("features.faults", "Developer features", "The switch of the developer features, read where the developer tools ask whether they are on", False, option_type="switch")
    PERFORMANCE = Option("faults.performance", "Performance monitoring", "How long requests, hooks and jobs take and what they read, reported to the agent when they run slow; off, none of it is measured or reported", True, option_type="switch", main_switch=DEVELOPER)
    INTERNAL = Option("faults.internal_feedback", "Internal feedback", "What the journal shows you of its own workings while you build it: the agent's hook lines and their durations in the terminal, and viewer updates made too early; off, none of it is shown", True, option_type="switch", main_switch=DEVELOPER)
    REPORT = Option("faults.report", "Report slow requests to the agent", "A request over its budget is marked in the chat and the agent is sent a line to fix it; off, the Developer tab still counts every request's time while the developer features are on", False, option_type="switch", main_switch=PERFORMANCE)
    HOOK_LINE_COPY = Option("faults.terminal_hook_lines", "Show the agent's hook lines in the terminal", "Every line the journal gives the agent in a hook is also shown to you in the agent's terminal; the agent gets its lines either way", False, option_type="switch", main_switch=INTERNAL)
    HOOK_TIME_COPY = Option("faults.terminal_hook_times", "Show each hook's duration in the terminal", "Each hook's answer shows you, in the agent's terminal, how long the journal took to answer it; the agent never receives the duration", False, option_type="switch", main_switch=INTERNAL)
    REQUEST = Option("faults.budget.request", "Points budget for a request that reads", "Points a request that reads may spend before it is reported, a row loaded, a write and a started kilobyte loaded a point each; 0 reports none", 30, unit="points", main_switch=REPORT)
    EDIT_BUDGET = Option("faults.budget.write", "Points budget for a request that writes", "Points a request that writes may spend before it is reported, a row loaded, a write and a started kilobyte loaded a point each; 0 reports none", 30, unit="points", main_switch=REPORT)
    REPEAT = Option("faults.repeat_minutes", "New slow requests report after", "Minutes since the last slow requests report before a new one is made of what gathered since, its mark written in the chat and the agent sent a line to read it; 0 makes one only", 5, unit="min", main_switch=REPORT)
    LOADS = Option("faults.count_loads", "Count the records each request reads", "Every record a request or a hook reads from the database is counted by its kind, shown with the newest requests and as totals since the last reset; off, nothing is counted", False, option_type="switch", main_switch=PERFORMANCE)
    STALL_STACKS = Option("faults.stall_stacks", "Write every thread's stack when a request stalls", "A request still running after five seconds writes the stack of every thread of the journal to its log, which shows what a stall waits on", False, option_type="switch", main_switch=PERFORMANCE)
    STAGE_TIMING = Option("faults.stage_times", "Time every stage of a hook", "Each stage a hook passes through, its entry, its transcript, each feature's facts read and each listener, adds its time to the Developer numbers, listed by journal developer averages", False, option_type="switch", main_switch=PERFORMANCE)
    EARLY_VIEWER_WRITE_WARNING = Option("faults.undeferred_viewer_writes", "Warn the agent of viewer updates made before a hook answers", "A listener that runs before a hook answers and writes a card or a chat mark, which belongs after the answer, adds a warning naming it to that hook's answer; off, it is only written to the faults log", False, option_type="switch", main_switch=INTERNAL)
    JOBS = Option("faults.jobs", "Tell the agent about slow jobs", "A background job whose tick runs longer than a second is logged while the developer features are on; on, the agent is also sent a line to fix it", False, option_type="switch", main_switch=PERFORMANCE)
